local mp     = require 'mp'
local utils  = require 'mp.utils'
local common = require 'src.common'

local M = {
    builtin_path = utils.join_path(mp.get_script_directory() or "", "tachytome.conf"),
    user_path    = nil,
    menu_lines   = {},
    configs      = {},
    hold         = false
}

local identifier = "tachytome"
local reserved   = { ["default.conf"] = true, ["user.conf"] = true }
local defaults   = nil
local override   = nil
local header     = {
    "# Generated by Tachytome and written again on every update, changes made here are lost",
    "# Put your changes in `user.conf` next to this file, it's loaded on top of this one",
    ""
}

local function typeconv(default, val)
    if type(default) == "boolean" then
        if val == "yes" then return true end
        if val == "no" then return false end
        return nil
    end
    if type(default) == "number" then return tonumber(val) end
    return val
end

local function set_opt(opts, key, val, where)
    if opts[key] == nil then
        if not override then mp.msg.warn(where .. " unknown key '" .. key .. "', ignoring") end
        return
    end
    local conv = typeconv(opts[key], val)
    if conv == nil then
        if not override then mp.msg.error(where .. " error converting value '" .. val .. "' for key '" .. key .. "'") end
        return
    end
    opts[key] = conv
end

local function overridden(path, key)
    return override and path == override.path and override.values[key] ~= nil
end

local function apply_override(path, opts, name)
    if not override or path ~= override.path then return end
    for key, val in pairs(override.values) do
        if val then set_opt(opts, key, val, name) end
    end
end

function M.config_path(name)
    return utils.join_path(common.get_conf_dir(), name .. ".conf")
end

local function parse_configs(val)
    local list = {}
    local seen = {}
    for entry in val:gmatch("[^,]+") do
        local name    = entry:match("^%s*(.-)%s*$")
        local enabled = name:sub(1, 1) ~= "!"
        if not enabled then name = name:sub(2):match("^%s*(.-)$") end
        name = name:gsub("%.conf$", "")
        if name ~= "" and not seen[name] and not reserved[name .. ".conf"] then
            seen[name]      = true
            list[#list + 1] = { name = name, enabled = enabled, exists = common.file_exists(M.config_path(name)) }
        end
    end
    return list, seen
end

local function discover_configs(list, seen)
    local found = {}
    for _, file in ipairs(utils.readdir(common.get_conf_dir(), "files") or {}) do
        local name = file:match("^(.+)%.conf$")
        if name and not reserved[file] and not seen[name] then found[#found + 1] = name end
    end
    table.sort(found)
    for _, name in ipairs(found) do
        list[#list + 1] = { name = name, enabled = false, exists = true }
    end
    return list
end

local parse_file

local function load_configs(val, where, opts, chunks)
    local list, seen = parse_configs(val)
    for _, c in ipairs(list) do
        local target = override and override.name == c.name
        if (c.enabled or target) and (c.exists or target) then
            parse_file(M.config_path(c.name), c.name .. ".conf", opts, chunks, "config")
        elseif c.enabled and not override then
            mp.msg.warn(where .. " config '" .. c.name .. "' not found at " .. M.config_path(c.name))
        end
    end
    if override and not override.loaded and override.name ~= "user" then
        parse_file(override.path, override.name .. ".conf", opts, chunks, "config")
    end
    M.configs = discover_configs(list, seen)
end

parse_file = function(path, name, opts, chunks, mode)
    local menu_lines = {}
    chunks[#chunks + 1] = menu_lines
    if override and path == override.path then override.loaded = true end
    local f = io.open(path, "r")
    if not f then return apply_override(path, opts, name) end

    local depth        = 0
    local n            = 0
    local configs_seen = false
    for raw in f:lines() do
        n = n + 1
        local line    = raw:gsub("\r$", "")
        local content = line
        local hash    = content:find("#", 1, true)
        if hash then content = content:sub(1, hash - 1) end
        content = content:match("^%s*(.-)%s*$")
        local where = name .. ":" .. n

        local eq = line:find("=", 1, true)
        if depth == 0 and eq and line:sub(1, 1) ~= "#" and not content:find("^menu%s") then
            local key = line:sub(1, eq - 1)
            if key ~= "configs" then
                if not overridden(path, key) then set_opt(opts, key, line:sub(eq + 1), where) end
            elseif mode == "config" then
                mp.msg.warn(where .. " configs only works in " .. M.user_path .. ", ignoring")
            elseif mode == "main" and configs_seen then
                mp.msg.warn(where .. " configs already set, ignoring")
            elseif mode == "main" then
                configs_seen = true
                load_configs(line:sub(eq + 1), where, opts, chunks)
                menu_lines          = {}
                chunks[#chunks + 1] = menu_lines
            end
        elseif content ~= "" or not line:find("%S") then
            menu_lines[#menu_lines + 1] = { text = content, where = where }
            if content:find("{$") then
                depth = depth + 1
            elseif content == "}" and depth > 0 then
                depth = depth - 1
            end
        end
    end
    f:close()
    apply_override(path, opts, name)

    if mode == "main" and not configs_seen then M.configs = discover_configs({}, {}) end
end

local function apply_script_opts(opts)
    local prefix = identifier .. "-"
    for key, val in pairs(mp.get_property_native("options/script-opts") or {}) do
        if key:sub(1, #prefix) == prefix then
            set_opt(opts, key:sub(#prefix + 1), val, "script-opts:")
        end
    end
end

local function read_lines(path)
    local lines = {}
    local f = io.open(path, "r")
    if not f then return lines end
    for line in f:lines() do lines[#lines + 1] = line:gsub("\r$", "") end
    f:close()
    return lines
end

local function configs_line(lines)
    for i, line in ipairs(lines) do
        if line:sub(1, 8) == "configs=" then return i end
    end
    return nil
end

local function option_rows(lines)
    local rows  = {}
    local depth = 0
    for i, line in ipairs(lines) do
        local content = line
        local hash    = content:find("#", 1, true)
        if hash then content = content:sub(1, hash - 1) end
        content = content:match("^%s*(.-)%s*$")
        local eq = line:find("=", 1, true)
        if depth == 0 and eq and line:sub(1, 1) ~= "#" and not content:find("^menu%s") then
            rows[#rows + 1] = { i = i, key = line:sub(1, eq - 1), val = line:sub(eq + 1) }
        elseif content:find("{$") then
            depth = depth + 1
        elseif content == "}" and depth > 0 then
            depth = depth - 1
        end
    end
    return rows
end

local function write_lines(path, lines, key)
    common.ensure_dir(common.get_conf_dir())
    local f = io.open(path, "w")
    if not f then
        mp.msg.warn("Failed to write " .. key .. " to " .. path)
        return false
    end
    f:write(#lines > 0 and table.concat(lines, "\n") .. "\n" or "")
    f:close()
    return true
end

function M.main_path()
    return M.config_path("user")
end

function M.default_path()
    return M.config_path("default")
end

local function ensure_main_conf()
    local main = M.main_path()
    if M.hold then return main end

    if not common.file_exists(main) and write_lines(main, {}, "user.conf") then
        mp.msg.info("Generated config at: " .. main)
    end
    return main
end

local function ensure_default_conf()
    local builtin = read_lines(M.builtin_path)
    if M.hold or #builtin == 0 then return M.builtin_path end

    local path  = M.default_path()
    local lines = {}
    for _, line in ipairs(header) do lines[#lines + 1] = line end
    for _, line in ipairs(builtin) do lines[#lines + 1] = line end
    if table.concat(read_lines(path), "\n") == table.concat(lines, "\n") then return path end

    if not write_lines(path, lines, "default.conf") then return M.builtin_path end
    mp.msg.info("Generated default config at: " .. path)
    return path
end

function M.read_options(opts)
    if defaults then
        for key, val in pairs(defaults) do opts[key] = val end
    else
        defaults = {}
        for key, val in pairs(opts) do defaults[key] = val end
    end
    M.menu_lines = {}
    M.configs    = {}
    M.user_path  = ensure_main_conf()
    local base   = ensure_default_conf()
    parse_file(base, base == M.builtin_path and "tachytome.conf (builtin)" or base, opts, M.menu_lines, "builtin")
    if override and override.name ~= "user" and not configs_line(read_lines(M.user_path)) then
        parse_file(override.path, override.name .. ".conf", opts, M.menu_lines, "config")
    end
    parse_file(M.user_path, M.user_path, opts, M.menu_lines, "main")
    apply_script_opts(opts)
end

function M.resolve(name, values)
    local configs    = M.configs
    local menu_lines = M.menu_lines
    local opts       = {}
    override = { name = name, path = M.config_path(name), values = values }
    M.read_options(opts)
    override     = nil
    M.configs    = configs
    M.menu_lines = menu_lines
    return opts
end

local function builtin_block(key)
    local lines = read_lines(M.builtin_path)
    for i, line in ipairs(lines) do
        if line:sub(1, #key + 1) == key .. "=" then
            local first = i
            while first > 1 and lines[first - 1]:sub(1, 1) == "#" do first = first - 1 end
            local block = {}
            for j = first, i - 1 do block[#block + 1] = lines[j] end
            return block
        end
    end
    return {}
end

function M.format(val)
    if type(val) == "boolean" then return val and "yes" or "no" end
    return tostring(val)
end

local function put_option(lines, key, val)
    local entry  = key .. "=" .. M.format(val)
    local prefix = key .. "="
    for i = #lines, (configs_line(lines) or 0) + 1, -1 do
        if lines[i]:sub(1, #prefix) == prefix then
            lines[i] = entry
            return
        end
    end
    if #lines > 0 and lines[#lines] ~= "" then lines[#lines + 1] = "" end
    for _, line in ipairs(builtin_block(key)) do lines[#lines + 1] = line end
    lines[#lines + 1] = entry
end

function M.write_options(list)
    if not M.user_path or M.hold then return false end
    local lines = read_lines(M.user_path)
    for _, o in ipairs(list) do put_option(lines, o.key, o.val) end
    return write_lines(M.user_path, lines, "options")
end

function M.write_option(key, val)
    return M.write_options({ { key = key, val = val } })
end

function M.keys()
    local list = {}
    for _, line in ipairs(read_lines(M.builtin_path)) do
        local key = line:match("^([%w_]+)=")
        if key and key ~= "configs" then list[#list + 1] = key end
    end
    return list
end

function M.default(key)
    return defaults and defaults[key]
end

function M.parse_value(key, text)
    if not defaults or defaults[key] == nil then return nil end
    return typeconv(defaults[key], text)
end

function M.describe(key)
    local out = {}
    for i, line in ipairs(builtin_block(key)) do out[i] = line:gsub("^# ?", "") end
    return out
end

function M.section(key)
    local current = nil
    for _, line in ipairs(read_lines(M.builtin_path)) do
        current = line:match("^## (.+)$") or current
        if line:sub(1, #key + 1) == key .. "=" then return current end
    end
    return nil
end

function M.file_options(name)
    local vals = {}
    for _, row in ipairs(option_rows(read_lines(M.config_path(name)))) do
        if row.key ~= "configs" and M.default(row.key) ~= nil then
            local conv    = M.parse_value(row.key, row.val)
            vals[row.key] = conv == nil and row.val or M.format(conv)
        end
    end
    return vals
end

local function remove_option(lines, key)
    local rows  = option_rows(lines)
    local block = builtin_block(key)
    for r = #rows, 1, -1 do
        local i = rows[r].i
        if rows[r].key == key then
            local first = i
            local match = i > #block
            for j = 1, #block do
                if lines[i - #block - 1 + j] ~= block[j] then match = false end
            end
            if match then first = i - #block end
            for _ = first, i do table.remove(lines, first) end
            if lines[first - 1] == "" and (lines[first] == nil or lines[first] == "") then table.remove(lines, first - 1) end
        end
    end
end

function M.save_options(name, values)
    if M.hold then return false end
    local path  = M.config_path(name)
    local lines = read_lines(path)
    for _, key in ipairs(M.keys()) do
        if values[key] == false then
            remove_option(lines, key)
        elseif values[key] then
            put_option(lines, key, values[key])
        end
    end
    return write_lines(path, lines, name .. ".conf")
end

function M.config_name_error(name)
    if name == "" or name:find("[%s/\\,!#=]") or name:sub(1, 1) == "." then return "configs_bad_name" end
    if reserved[name:lower() .. ".conf"] then return "configs_reserved" end
    return nil
end

function M.create_config(name)
    if M.hold then return false end
    return write_lines(M.config_path(name), {}, name .. ".conf")
end

function M.rename_config(from, to)
    if M.hold then return false end
    local ok, err = os.rename(M.config_path(from), M.config_path(to))
    if not ok then mp.msg.warn("Failed to rename " .. from .. ".conf to " .. to .. ".conf: " .. tostring(err)) end
    return ok
end

function M.delete_config(name)
    if M.hold then return false end
    local ok, err = os.remove(M.config_path(name))
    if not ok then mp.msg.warn("Failed to delete " .. name .. ".conf: " .. tostring(err)) end
    return ok
end

function M.write_configs(list)
    if not M.user_path or M.hold then return false end
    local names = {}
    for _, c in ipairs(list) do names[#names + 1] = (c.enabled and "" or "!") .. c.name end
    local entry = "configs=" .. table.concat(names, ",")
    local lines = read_lines(M.user_path)

    local idx   = configs_line(lines)
    if idx then
        lines[idx] = entry
        return write_lines(M.user_path, lines, "configs")
    end

    local block = builtin_block("configs")
    block[#block + 1] = entry
    if #lines > 0 then block[#block + 1] = "" end
    for i = #block, 1, -1 do table.insert(lines, 1, block[i]) end
    return write_lines(M.user_path, lines, "configs")
end

return M
